//! Column numbering and the table constraints the structure forms add.
use super::ForeignTarget;

/// How a column numbers new rows.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum Identity {
    /// Plain column.
    #[default]
    None,
    /// `GENERATED ALWAYS AS IDENTITY` (`PostgreSQL`).
    Always,
    /// `GENERATED BY DEFAULT AS IDENTITY` (`PostgreSQL`).
    ByDefault,
    /// `AUTO_INCREMENT` (`MySQL`) or `AUTOINCREMENT` (`SQLite` key column).
    AutoIncrement,
}

/// What happens to referencing rows when the referenced row changes.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum ReferentialAction {
    /// `NO ACTION` (the engine's default).
    #[default]
    NoAction,
    /// `RESTRICT`.
    Restrict,
    /// `CASCADE`.
    Cascade,
    /// `SET NULL`.
    SetNull,
    /// `SET DEFAULT`.
    SetDefault,
}

impl ReferentialAction {
    /// The SQL spelling, e.g. `SET NULL`.
    #[must_use]
    pub fn sql(self) -> &'static str {
        match self {
            Self::NoAction => "NO ACTION",
            Self::Restrict => "RESTRICT",
            Self::Cascade => "CASCADE",
            Self::SetNull => "SET NULL",
            Self::SetDefault => "SET DEFAULT",
        }
    }
}

/// A foreign key to add.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct NewForeignKey {
    /// Constraint name; the server picks one when `None`.
    pub name: Option<String>,
    /// Referencing columns (final names), in key order.
    pub columns: Vec<String>,
    /// Referenced table and columns.
    pub target: ForeignTarget,
    /// `ON DELETE` action.
    pub on_delete: ReferentialAction,
    /// `ON UPDATE` action.
    pub on_update: ReferentialAction,
}

/// A check constraint to add.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct NewCheck {
    /// Constraint name; the server picks one when `None`.
    pub name: Option<String>,
    /// The boolean SQL expression, without `CHECK ( … )`.
    pub expression: String,
}
